<script setup lang="ts">
// 顶部「模式状态条」：常驻所有 tab，一眼回答「系统在不在跑、以什么模式跑、预算还剩多少」。
// 数据来自总览（auto_consume/预算/心跳）与 worker 心跳配置（judge 每轮 tick 写入 kv）。
import { computed } from "vue";
import { fmtAgo } from "./enrich-common";
import type { EnrichOverview, EnrichWorkerConfig } from "@/types/problem-enrichment";

const props = defineProps<{
  overview: EnrichOverview | null;
  workerConfig: EnrichWorkerConfig | null;
}>();

const emit = defineEmits<{
  (e: "toggle-auto-consume", enabled: boolean): void;
}>();

// 运行模式：已停用 > 干跑 > 等待心跳 > 自动批量 > 手动试运行
const mode = computed<{
  label: string;
  theme: string;
  desc: string;
} | null>(() => {
  const cfg = props.workerConfig;
  const ov = props.overview;
  if (!cfg) {
    return null;
  }
  if (cfg.enabled === false) {
    return {
      label: "已停用",
      theme: "default",
      desc: "judge 配置 ai.problem-enrichment.enabled=false，worker 未启动；需要富化时在 judge 配置中开启后重新部署",
    };
  }
  if (cfg.dry_run) {
    return { label: "干跑模式", theme: "default", desc: "走完整流程但不调 LLM，用于验证流水线；注意干跑会把指纹落库" };
  }
  if (!cfg.heartbeat_time) {
    return { label: "等待 worker 心跳", theme: "warning", desc: "judge 进程未部署或尚未跑过一轮，后台暂无真实运行参数" };
  }
  if (ov?.auto_consume) {
    return { label: "自动批量运行中", theme: "success", desc: "worker 每轮自动回收卡死题并批量认领待处理题目" };
  }
  return { label: "手动试运行", theme: "warning", desc: "worker 只处理人工单独重判的题，不自动烧额度" };
});

const tokenPct = computed(() => {
  const b = props.overview?.budget;
  if (!b || b.token_limit <= 0) {
    return 0;
  }
  return Math.min(100, Math.round((b.token_used / b.token_limit) * 100));
});

const problemPct = computed(() => {
  const b = props.overview?.budget;
  if (!b || b.problem_limit <= 0) {
    return 0;
  }
  return Math.min(100, Math.round((b.problem_used / b.problem_limit) * 100));
});

const fmtNum = (n: number): string => {
  if (n >= 1_000_000) {
    return `${(n / 1_000_000).toFixed(1)}M`;
  }
  if (n >= 1_000) {
    return `${(n / 1_000).toFixed(1)}k`;
  }
  return String(n);
};
</script>

<template>
  <div v-if="overview" class="mode-bar">
    <!-- 运行模式 -->
    <t-tooltip :content="mode?.desc || ''">
      <t-tag v-if="mode" :theme="mode.theme" variant="light" class="mode-item">
        {{ mode.label }}
      </t-tag>
    </t-tooltip>

    <!-- 自动批量切换（停用/干跑状态下不提供） -->
    <t-popconfirm
      v-if="mode && workerConfig?.enabled !== false && !workerConfig?.dry_run && !overview.auto_consume"
      content="开启后 worker 会自动回收卡死题并批量处理全部待处理题目，开始持续消耗模型额度（仍受每日题数/token 限额保护）。确定开启全量？"
      @confirm="emit('toggle-auto-consume', true)"
    >
      <t-button size="small" theme="primary" variant="outline">开启自动批量</t-button>
    </t-popconfirm>
    <t-button
      v-else-if="mode && workerConfig?.enabled !== false && !workerConfig?.dry_run && overview.auto_consume"
      size="small"
      variant="outline"
      @click="emit('toggle-auto-consume', false)"
    >
      切回手动试运行
    </t-button>

    <!-- worker 心跳 -->
    <t-tag
      v-if="overview.worker.heartbeat_time"
      :theme="overview.worker.alive ? 'success' : 'danger'"
      variant="outline"
      class="mode-item"
    >
      worker 心跳 {{ fmtAgo(overview.worker.heartbeat_time) }}
      {{ overview.worker.alive ? "" : "（已离线）" }}
    </t-tag>
    <t-tag v-else theme="warning" variant="outline" class="mode-item">worker 无心跳</t-tag>

    <!-- 今日预算 -->
    <t-tooltip
      :content="`今日已消耗 token ${overview.budget.token_used.toLocaleString()} / ${overview.budget.token_limit > 0 ? overview.budget.token_limit.toLocaleString() : '不限'}`"
    >
      <span class="mode-budget">
        <span class="mode-budget-label">token</span>
        <span class="mode-budget-bar">
          <span
            class="mode-budget-fill"
            :class="{ 'mode-budget-danger': tokenPct >= 90 }"
            :style="{ width: `${tokenPct}%` }"
          />
        </span>
        <span class="mode-budget-text">
          {{ fmtNum(overview.budget.token_used) }}/{{ overview.budget.token_limit > 0 ? fmtNum(overview.budget.token_limit) : "∞" }}
        </span>
      </span>
    </t-tooltip>
    <t-tooltip
      :content="`今日已富化题目 ${overview.budget.problem_used} / ${overview.budget.problem_limit > 0 ? overview.budget.problem_limit : '不限'}`"
    >
      <span class="mode-budget">
        <span class="mode-budget-label">题数</span>
        <span class="mode-budget-bar">
          <span
            class="mode-budget-fill"
            :class="{ 'mode-budget-danger': problemPct >= 90 }"
            :style="{ width: `${problemPct}%` }"
          />
        </span>
        <span class="mode-budget-text">
          {{ overview.budget.problem_used }}/{{ overview.budget.problem_limit > 0 ? overview.budget.problem_limit : "∞" }}
        </span>
      </span>
    </t-tooltip>
  </div>
</template>

