<script setup lang="ts">
// 总览 tab：总体进度（分段进度条 + 速率/ETA）→ 今日预算 → 当前活动（实时流水线）→
// 最近失败 → 状态分布 → 阶段耗时。5 秒轮询，页面不可见时暂停。
import { computed, onBeforeUnmount, onMounted } from "vue";
import { fmtEta, fmtSec, fmtTime, stageText } from "./enrich-common";
import EnrichPipelineSteps from "./EnrichPipelineSteps.vue";
import type { EnrichOverview } from "@/types/problem-enrichment";

const props = defineProps<{
  overview: EnrichOverview | null;
  loading: boolean;
}>();

const emit = defineEmits<{
  (e: "refresh"): void;
  (e: "goto-status", status: number | null): void;
  (e: "open-detail", problemId: number): void;
  (e: "requeue", problemId: number): void;
}>();

// 5s 轮询：页面不可见时暂停，卸载时清理
let timer: ReturnType<typeof setInterval> | null = null;
const polling = () => {
  if (document.visibilityState === "visible") {
    emit("refresh");
  }
};
const onVisibility = () => {
  if (document.visibilityState === "visible") {
    polling();
  }
};
onMounted(() => {
  timer = setInterval(polling, 5000);
  document.addEventListener("visibilitychange", onVisibility);
});
onBeforeUnmount(() => {
  if (timer) {
    clearInterval(timer);
    timer = null;
  }
  document.removeEventListener("visibilitychange", onVisibility);
});

// ── 分段进度条 ──
const segments = computed(() => {
  const ov = props.overview;
  if (!ov) {
    return [];
  }
  return [
    { key: "success", label: "成功", value: ov.success, cls: "seg-success" },
    { key: "human", label: "人工定稿", value: ov.progress.human_curated, cls: "seg-human" },
    { key: "failed", label: "失败", value: ov.failed, cls: "seg-failed" },
    { key: "running", label: "处理中", value: ov.running, cls: "seg-running" },
    { key: "init", label: "待处理", value: ov.init + ov.queued, cls: "seg-init" },
  ];
});

const segWidth = (v: number): string => {
  const total = props.overview?.problem_total ?? 0;
  if (total <= 0) {
    return "0%";
  }
  return `${Math.max(v > 0 ? 0.8 : 0, (v / total) * 100)}%`;
};

const rateText = computed(() => {
  const p = props.overview?.progress;
  if (!p || p.rate_per_hour <= 0) {
    return "—";
  }
  return `${p.rate_per_hour.toFixed(1)} 题/h`;
});

const etaText = computed(() => fmtEta(props.overview?.progress.eta_minutes ?? -1));

// 预算触顶提示
const budgetBlocked = computed(() => {
  const b = props.overview?.budget;
  if (!b) {
    return false;
  }
  return (b.token_limit > 0 && b.token_used >= b.token_limit) ||
    (b.problem_limit > 0 && b.problem_used >= b.problem_limit);
});

const budgetTokenPct = computed(() => {
  const b = props.overview?.budget;
  if (!b || b.token_limit <= 0) {
    return 0;
  }
  return Math.min(100, Math.round((b.token_used / b.token_limit) * 100));
});

const budgetProblemPct = computed(() => {
  const b = props.overview?.budget;
  if (!b || b.problem_limit <= 0) {
    return 0;
  }
  return Math.min(100, Math.round((b.problem_used / b.problem_limit) * 100));
});
</script>

<template>
  <t-loading :loading="loading && !overview" size="small">
    <template v-if="overview">
      <!-- ── 总体进度 ── -->
      <div class="ov-block">
        <div class="ov-block-title">总体进度</div>
        <div class="ov-progress-bar">
          <span
            v-for="seg in segments"
            :key="seg.key"
            class="ov-progress-seg"
            :class="seg.cls"
            :style="{ width: segWidth(seg.value) }"
            :title="`${seg.label} ${seg.value}`"
          />
        </div>
        <div class="ov-progress-legend">
          <span v-for="seg in segments" :key="seg.key" class="ov-legend-item">
            <i class="ov-legend-dot" :class="seg.cls" />{{ seg.label }} {{ seg.value }}
          </span>
        </div>
        <div class="ov-progress-meta">
          覆盖率 {{ (overview.coverage_rate * 100).toFixed(1) }}% ·
          待处理 {{ overview.progress.pending_total }} ·
          今日已富化 {{ overview.progress.today_problems }} 题 ·
          今日速度 {{ rateText }} ·
          预计完成 ≈ {{ etaText }}
        </div>
      </div>

      <!-- ── 今日预算 ── -->
      <div class="ov-block">
        <div class="ov-block-title">今日预算</div>
        <t-alert
          v-if="budgetBlocked"
          theme="error"
          class="ov-alert"
          message="今日预算已触顶：worker 将暂停认领新题，等待明日零点重置或调高 judge 配置限额。"
        />
        <div class="ov-budget-row">
          <span class="ov-budget-label">token</span>
          <span class="ov-budget-bar">
            <span
              class="ov-budget-fill"
              :class="{ 'ov-budget-danger': budgetTokenPct >= 90 }"
              :style="{ width: `${budgetTokenPct}%` }"
            />
          </span>
          <span class="ov-budget-text">
            {{ overview.budget.token_used.toLocaleString() }} /
            {{ overview.budget.token_limit > 0 ? overview.budget.token_limit.toLocaleString() : "不限" }}
          </span>
        </div>
        <div class="ov-budget-row">
          <span class="ov-budget-label">题数</span>
          <span class="ov-budget-bar">
            <span
              class="ov-budget-fill"
              :class="{ 'ov-budget-danger': budgetProblemPct >= 90 }"
              :style="{ width: `${budgetProblemPct}%` }"
            />
          </span>
          <span class="ov-budget-text">
            {{ overview.budget.problem_used }} /
            {{ overview.budget.problem_limit > 0 ? overview.budget.problem_limit : "不限" }}
          </span>
        </div>
      </div>

      <!-- ── 当前活动 ── -->
      <div class="ov-block">
        <div class="ov-block-title">
          当前活动（5s 轮询）
          <span v-if="!overview.active.length" class="ov-block-empty">暂无处理中的题目</span>
        </div>
        <div v-for="a in overview.active" :key="a.problem_id" class="ov-active-row">
          <t-button variant="text" class="ov-active-title" @click="emit('open-detail', a.problem_id)">
            {{ a.problem_key || `#${a.problem_id}` }} {{ a.problem_title || "" }}
          </t-button>
          <EnrichPipelineSteps :steps="a.steps" size="md" />
          <span class="ov-active-meta">
            {{ stageText[a.stage] || a.stage || "—" }} · 第 {{ a.attempt }} 次 · 更新
            {{ fmtTime(a.modify_time) }}
          </span>
        </div>
      </div>

      <!-- ── 最近失败 ── -->
      <div v-if="overview.recent_failures.length" class="ov-block">
        <div class="ov-block-title">最近失败</div>
        <div v-for="f in overview.recent_failures" :key="f.problem_id" class="ov-fail-row">
          <t-button variant="text" @click="emit('open-detail', f.problem_id)">
            {{ f.problem_key || `#${f.problem_id}` }} {{ f.problem_title || "" }}
          </t-button>
          <span class="ov-fail-msg" :title="f.message">{{ f.message || "—" }}</span>
          <span class="ov-active-meta">{{ fmtTime(f.modify_time) }}</span>
          <t-button size="small" variant="text" theme="primary" @click="emit('requeue', f.problem_id)">
            重判
          </t-button>
        </div>
      </div>

      <!-- ── 状态分布（点击下钻） ── -->
      <div class="ov-cards">
        <div class="ov-card ov-clickable" @click="emit('goto-status', 0)">
          <div class="ov-value">{{ overview.init }}</div>
          <div class="ov-label">未处理</div>
        </div>
        <div class="ov-card ov-clickable" @click="emit('goto-status', 1)">
          <div class="ov-value ov-warn">{{ overview.queued }}</div>
          <div class="ov-label">排队</div>
        </div>
        <div class="ov-card ov-clickable" @click="emit('goto-status', 2)">
          <div class="ov-value ov-primary">{{ overview.running }}</div>
          <div class="ov-label">处理中</div>
        </div>
        <div class="ov-card ov-clickable" @click="emit('goto-status', 3)">
          <div class="ov-value ov-success">{{ overview.success }}</div>
          <div class="ov-label">成功</div>
        </div>
        <div class="ov-card ov-clickable" @click="emit('goto-status', 4)">
          <div class="ov-value ov-danger">{{ overview.failed }}</div>
          <div class="ov-label">失败</div>
        </div>
        <div class="ov-card">
          <div class="ov-value ov-success">{{ overview.today.success }}</div>
          <div class="ov-label">今日调用成功</div>
        </div>
        <div class="ov-card">
          <div class="ov-value" :class="overview.today.success_rate < 0.8 ? 'ov-danger' : 'ov-success'">
            {{ (overview.today.success_rate * 100).toFixed(0) }}%
          </div>
          <div class="ov-label">今日成功率</div>
        </div>
        <div class="ov-card">
          <div class="ov-value ov-sm">{{ overview.today.success_tokens.toLocaleString() }}</div>
          <div class="ov-label">今日成功 token</div>
        </div>
      </div>

      <!-- ── 手动试运行引导 ── -->
      <t-alert
        v-if="!overview.auto_consume"
        theme="warning"
        class="ov-alert"
        :message="`手动试运行中：worker 只会处理你在题目列表对单题点「重判」的题目；其余 ${overview.progress.pending_total} 道待处理题不会自动消耗模型额度。先手动验证几题，确认无误后再「开启自动批量」全量处理。`"
      />

      <!-- ── worker 健康 ── -->
      <t-alert
        v-if="overview.stale_workers.length"
        theme="error"
        class="ov-alert"
        :message="`检测到 ${overview.stale_workers.length} 个疑似卡死/空转 worker：${overview.stale_workers.join('、')}（心跳超过 ${overview.worker.stale_timeout_sec}s）。可对卡死题执行「重判」夺回。`"
      />
      <div v-if="overview.workers.length" class="ov-workers">
        <t-tag
          v-for="w in overview.workers"
          :key="w.worker"
          :theme="overview.stale_workers.includes(w.worker) ? 'danger' : 'success'"
          variant="light"
          class="ov-worker-tag"
        >
          {{ w.worker }}：{{ w.count }} 题 · 最老心跳 {{ fmtTime(w.oldest_modify) }}
        </t-tag>
      </div>

      <!-- ── 阶段耗时 ── -->
      <div v-if="overview.stage_latency.length" class="ov-latency">
        <span class="ov-latency-title">今日各阶段平均耗时：</span>
        <t-tag v-for="l in overview.stage_latency" :key="l.stage" variant="outline" class="ov-worker-tag">
          {{ stageText[l.stage] || l.stage }} {{ fmtSec(Math.round(l.avg_ms)) }}
          <span v-if="l.max_ms >= 180000" class="ov-max-slow">（峰值 {{ fmtSec(l.max_ms) }} 超时）</span>
        </t-tag>
      </div>
    </template>
  </t-loading>
</template>

