// 富化后台各 tab 组件共享的常量映射与工具函数。
// 原 ManageProblemEnrichment.vue 拆分后这些定义集中于此，避免各组件重复。

// 父组件注入给各 tab 的跨视图动作（详情抽屉/人工标注抽屉/重判/全局刷新）。
// review tab 用 openCurator 注册保存/驳回回调，实现「保存并下一条」的审核流。
export interface EnrichActions {
  openDetail(problemId: number): void;
  openCurator(
    problemId: number,
    taskType: string,
    reviewMode?: boolean,
    onSaved?: (payload: { taskType: string; advance: boolean }) => void,
    onRejected?: (payload: { annotationId: number }) => void
  ): void;
  requeue(problemId: number): Promise<void>;
  refreshAll(): void;
}


