// 难度档名（与后端 EnrichDifficultyGradeNames 对齐）
export const gradeName = (grade: number): string =>
  ["", "入门", "普及", "提高", "省选", "NOI"][grade] ?? "—";

export const fmtTime = (s?: string): string => (s ? new Date(s).toLocaleString() : "—");

export const fmtSec = (ms: number): string =>
  ms >= 1000 ? `${(ms / 1000).toFixed(1)}s` : `${ms}ms`;

// 预计完成时间的展示：分钟 → "2h10m" / "35m"
export const fmtEta = (minutes: number): string => {
  if (minutes < 0) {
    return "—";
  }
  if (minutes < 1) {
    return "<1m";
  }
  const h = Math.floor(minutes / 60);
  const m = Math.round(minutes % 60);
  return h > 0 ? `${h}h${m}m` : `${m}m`;
};

// 心跳时间差 → "12s 前" / "3m 前" / "2h 前"
export const fmtAgo = (iso?: string): string => {
  if (!iso) {
    return "—";
  }
  const diff = Date.now() - new Date(iso).getTime();
  if (diff < 0) {
    return "刚刚";
  }
  if (diff < 60_000) {
    return `${Math.floor(diff / 1000)}s 前`;
  }
  if (diff < 3600_000) {
    return `${Math.floor(diff / 60_000)}m 前`;
  }
  return `${Math.floor(diff / 3600_000)}h 前`;
};
