<script setup lang="ts">
// 题目智能富化后台：5 tab 骨架 + 常驻模式状态条 + 跨 tab 的产出详情/人工标注抽屉。
// 各 tab 为独立组件（总览/题目列表/产出与审核/词表治理/黄金集一致率），
// 父组件只承担：总览数据（模式条与总览 tab 共用）、自动批量开关、跨视图动作分发。
import { onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, type GlobalProperties } from "@/util/tips";
import {
  GetEnrichOverview,
  GetEnrichWorkerConfig,
  PostEnrichAutoConsumeSet,
  PostEnrichRejudge,
} from "@/apis/problem-enrichment";
import type { EnrichActions } from "./enrich-common";
import EnrichModeBar from "./EnrichModeBar.vue";
import EnrichOverviewTab from "./EnrichOverviewTab.vue";
import EnrichStateTab from "./EnrichStateTab.vue";
import EnrichReviewTab from "./EnrichReviewTab.vue";
import EnrichTagTab from "./EnrichTagTab.vue";
import EnrichGoldenTab from "./EnrichGoldenTab.vue";
import EnrichProblemDetailDrawer from "./EnrichProblemDetailDrawer.vue";
import EnrichCuratorDrawer from "./EnrichCuratorDrawer.vue";
import type { EnrichOverview, EnrichWorkerConfig } from "@/types/problem-enrichment";

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;

const activeTab = ref("overview");

// ── 总览数据（模式条 + 总览 tab 共用） ──
const overview = ref<EnrichOverview | null>(null);
const overviewLoading = ref(false);
const workerConfig = ref<EnrichWorkerConfig | null>(null);

const fetchWorkerConfig = async () => {
  try {
    const res = await GetEnrichWorkerConfig();
    if (res.code === 0) {
      workerConfig.value = res.data;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  }
};

const fetchOverview = async () => {
  overviewLoading.value = true;
  try {
    const res = await GetEnrichOverview();
    if (res.code === 0 && res.data) {
      // 后端 nil 切片会序列化为 null，统一兜底避免模板读取 .length 时渲染崩溃
      const d = res.data;
      overview.value = {
        ...d,
        today: d.today ?? { total: 0, success: 0, fail: 0, running: 0, success_tokens: 0, success_rate: 0 },
        progress: d.progress ?? {
          human_curated: 0,
          finished: 0,
          pending_total: 0,
          today_problems: 0,
          rate_per_hour: 0,
          eta_minutes: -1,
        },
        budget: d.budget ?? { token_limit: 0, token_used: 0, problem_limit: 0, problem_used: 0 },
        worker: d.worker ?? { alive: false, heartbeat_time: "", interval_seconds: 0, stale_timeout_sec: 600 },
        workers: d.workers ?? [],
        stale_workers: d.stale_workers ?? [],
        active: d.active ?? [],
        recent_failures: d.recent_failures ?? [],
        stage_latency: d.stage_latency ?? [],
      };
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  } finally {
    overviewLoading.value = false;
  }
};

// ── 跨视图动作 ──
// dataVersion：外部动作（重判/人工定稿/切换模式）后递增，列表与审核 tab 据此刷新
const dataVersion = ref(0);
const refreshAll = () => {
  dataVersion.value += 1;
  fetchOverview();
  fetchWorkerConfig();
};

// 题目列表筛选下钻（总览点击状态卡 → 切到列表并应用筛选）
const stateFilterReq = ref<{ statuses: number[]; seq: number } | null>(null);
const gotoStatus = (status: number | null) => {
  activeTab.value = "state";
  stateFilterReq.value = { statuses: status == null ? [] : [status], seq: Date.now() };
};

// ── 产出详情抽屉 ──
const detailVisible = ref(false);
const detailProblemId = ref(0);
const openDetail = (problemId: number) => {
  detailProblemId.value = problemId;
  detailVisible.value = true;
};

// ── 人工标注 / 校正抽屉（审核流注册保存/驳回回调，实现「保存并下一条」） ──
const curatorVisible = ref(false);
const curatorProblemId = ref(0);
const curatorTaskType = ref("summary");
const curatorReviewMode = ref(false);
const curatorCallbacks = ref<{
  onSaved?: (payload: { taskType: string; advance: boolean }) => void;
  onRejected?: (payload: { annotationId: number }) => void;
}>({});

const openCurator: EnrichActions["openCurator"] = (problemId, taskType, reviewMode = false, onSaved, onRejected) => {
  curatorProblemId.value = problemId;
  curatorTaskType.value = taskType;
  curatorReviewMode.value = reviewMode;
  curatorCallbacks.value = { onSaved, onRejected };
  curatorVisible.value = true;
};

const onCuratorVisibleChange = (v: boolean) => {
  curatorVisible.value = v;
  if (!v && !curatorReviewMode.value) {
    refreshAll();
  }
};

// 校正抽屉保存：先让注册方（审核 tab）推进队列，再全局刷新
const onCuratorSaved = ({ taskType, advance }: { taskType: string; advance: boolean }) => {
  curatorCallbacks.value.onSaved?.({ taskType, advance });
  refreshAll();
};

const onCuratorRejected = ({ annotationId }: { annotationId: number }) => {
  curatorCallbacks.value.onRejected?.({ annotationId });
  refreshAll();
};

// ── 重判（跨视图共用动作） ──
const requeue = async (problemId: number) => {
  try {
    const res = await PostEnrichRejudge(problemId);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "已强制重新入队，judge 将重新处理");
      refreshAll();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

// ── 自动批量开关 ──
const setAutoConsume = async (enabled: boolean) => {
  try {
    const res = await PostEnrichAutoConsumeSet(enabled);
    if (res.code === 0) {
      ShowTextTipsInfo(
        globalProperties,
        enabled ? "已开启自动批量处理，worker 将开始全量处理" : "已切回手动试运行，worker 只处理单独重判的题"
      );
      await fetchOverview();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

// 注入给各 tab 的动作集合
const actions: EnrichActions = {
  openDetail,
  openCurator,
  requeue,
  refreshAll,
};

onMounted(() => {
  fetchWorkerConfig();
  fetchOverview();
});
</script>

<template>
  <div class="enrich-admin">
    <t-card class="enrich-header-card">
      <div class="enrich-header">
        <h2>题目智能富化后台</h2>
      </div>
      <p class="enrich-subtitle">
        摘要 / 标签 / 难度 / 质量由 AI 后处理流水线产出，支持人工校正定稿与手动重判。质量分与改进建议仅内部可见；候选标签需经生命周期治理后进入正式词表。
      </p>
    </t-card>

    <!-- 常驻模式状态条：运行模式 / 自动批量开关 / worker 心跳 / 今日预算 -->
    <EnrichModeBar
      :overview="overview"
      :worker-config="workerConfig"
      @toggle-auto-consume="setAutoConsume"
    />

    <t-card class="enrich-body-card">
      <t-tabs v-model="activeTab">
        <t-tab-panel value="overview" label="总览">
          <EnrichOverviewTab
            :overview="overview"
            :loading="overviewLoading"
            @refresh="fetchOverview"
            @goto-status="gotoStatus"
            @open-detail="openDetail"
            @requeue="requeue"
          />
        </t-tab-panel>

        <t-tab-panel value="state" label="题目列表">
          <EnrichStateTab
            :data-version="dataVersion"
            :filter-request="stateFilterReq"
            @open-detail="openDetail"
            @open-curator="openCurator"
          />
        </t-tab-panel>

        <t-tab-panel value="review" label="产出与审核">
          <EnrichReviewTab :data-version="dataVersion" :actions="actions" />
        </t-tab-panel>

        <t-tab-panel value="tag" label="词表治理">
          <EnrichTagTab />
        </t-tab-panel>

        <t-tab-panel value="golden" label="黄金集与一致率">
          <EnrichGoldenTab :actions="actions" />
        </t-tab-panel>
      </t-tabs>
    </t-card>

    <!-- 题目产出详情抽屉（只读） -->
    <EnrichProblemDetailDrawer
      v-model:visible="detailVisible"
      :problem-id="detailProblemId"
      :data-version="dataVersion"
      @open-curator="openCurator"
      @requeue="requeue"
    />

    <!-- 人工标注 / 校正抽屉 -->
    <EnrichCuratorDrawer
      :visible="curatorVisible"
      :problem-id="curatorProblemId"
      :initial-task-type="curatorTaskType"
      :review-mode="curatorReviewMode"
      @saved="onCuratorSaved"
      @rejected="onCuratorRejected"
      @update:visible="onCuratorVisibleChange"
    />
  </div>
</template>

